/**
 * Reads a Docusaurus `sidebars.js` or `sidebars.ts` as text, never running it. A sidebar file is a JavaScript object
 * literal, so a small tokenizer and literal parser recover each sidebar's order, its categories, and its links. The
 * result is the engine's `docs` navigation list.
 *
 * A page entry takes the imported page's title and URL; a `link` entry keeps its label and destination; a category
 * keeps its label and children. This engine's navigation groups hold links only, so a nested category is flattened
 * into its parent, in place. An `autogenerated` list is rebuilt from the section's folders: each folder becomes a
 * group titled by its `_category_` file (or the folder name) and ordered by `position`, while each page keeps its
 * `sidebar_position` order.
 */
import type { Diagnostic, NavGroup, NavItem, NavLink } from "../../contracts/index.ts";

/** One imported page a sidebar entry may name. */
export interface SidebarPage {
  /** The page's Docusaurus doc id: its path inside the docs section, without the extension. */
  readonly id: string;
  /** The label a sidebar entry shows when it gives none: `sidebar_label`, else `title`. */
  readonly title: string;
  /** The site-root URL the page will answer at. */
  readonly url: string;
  /** Front matter `sidebar_position`, which orders an autogenerated list. */
  readonly position?: number;
}

/** The label and order a folder's `_category_.json` or `_category_.yml` gives it. */
export interface CategoryMeta {
  readonly label?: string;
  readonly position?: number;
}

/** What a sidebars file contributed. */
export interface SidebarImport {
  /** The navigation entries the file lists, in declaration order; empty when it has no readable sidebar. */
  readonly items: readonly NavItem[];
  readonly diagnostics: readonly Diagnostic[];
}

type TokenKind = "string" | "word" | "punct";

interface Token {
  readonly kind: TokenKind;
  readonly text: string;
  readonly line: number;
}

type Literal =
  | { readonly kind: "string"; readonly text: string; readonly line: number }
  | { readonly kind: "array"; readonly items: readonly Literal[]; readonly line: number }
  | { readonly kind: "object"; readonly entries: readonly Field[]; readonly line: number };

interface Field {
  readonly key: string;
  readonly value: Literal;
  readonly line: number;
}

/** A cursor over the token list; the parser advances it. */
interface Cursor {
  readonly tokens: readonly Token[];
  at: number;
}

const WORD = /[A-Za-z0-9_$]/;
const CLOSERS = new Set([",", "]", "}", ")", ";", "="]);
const ANCHORS = new Set(["exports", "default", "sidebars"]);

/** Splits JavaScript into strings, words, and punctuation, dropping whitespace and comments. */
function tokenize(source: string): Token[] {
  const tokens: Token[] = [];
  let line = 1;
  for (let at = 0; at < source.length; ) {
    const char = source[at]!;
    if (char === "\n") {
      line += 1;
      at += 1;
      continue;
    }
    if (char === " " || char === "\t" || char === "\r") {
      at += 1;
      continue;
    }
    if (char === "/" && source[at + 1] === "/") {
      const end = source.indexOf("\n", at);
      at = end === -1 ? source.length : end;
      continue;
    }
    if (char === "/" && source[at + 1] === "*") {
      const end = source.indexOf("*/", at + 2);
      const stop = end === -1 ? source.length : end + 2;
      for (let index = at; index < stop; index += 1) if (source[index] === "\n") line += 1;
      at = stop;
      continue;
    }
    if (char === '"' || char === "'" || char === "`") {
      const startLine = line;
      let text = "";
      at += 1;
      while (at < source.length && source[at] !== char) {
        if (source[at] === "\\") {
          const next = source[at + 1] ?? "";
          text += next === "n" ? "\n" : next === "t" ? "\t" : next;
          at += 2;
          continue;
        }
        if (source[at] === "\n") line += 1;
        text += source[at];
        at += 1;
      }
      at += 1;
      tokens.push({ kind: "string", text, line: startLine });
      continue;
    }
    if (WORD.test(char)) {
      const start = at;
      while (at < source.length && WORD.test(source[at]!)) at += 1;
      tokens.push({ kind: "word", text: source.slice(start, at), line });
      continue;
    }
    tokens.push({ kind: "punct", text: char, line });
    at += 1;
  }
  return tokens;
}

/** Skips a spread (`...items`) or another expression the parser cannot resolve. */
function skipExpression(cursor: Cursor): void {
  while (cursor.at < cursor.tokens.length) {
    const token = cursor.tokens[cursor.at]!;
    if (token.kind === "punct" && CLOSERS.has(token.text)) return;
    cursor.at += 1;
    if (token.kind === "word" || token.kind === "string") return;
  }
}

/** Skips one object entry the parser cannot read, up to the comma or closing brace that ends it. */
function skipEntry(cursor: Cursor): void {
  let depth = 0;
  while (cursor.at < cursor.tokens.length) {
    const token = cursor.tokens[cursor.at]!;
    if (token.kind === "punct") {
      if (token.text === "{" || token.text === "[" || token.text === "(") depth += 1;
      else if (token.text === "}" || token.text === "]" || token.text === ")") {
        if (depth === 0) return;
        depth -= 1;
      } else if (token.text === "," && depth === 0) {
        cursor.at += 1;
        return;
      }
    }
    cursor.at += 1;
  }
}

/** Reads one literal at the cursor and advances past it. */
function literal(cursor: Cursor): Literal | undefined {
  const token = cursor.tokens[cursor.at];
  if (token === undefined) return undefined;
  if (token.kind === "string") {
    cursor.at += 1;
    return { kind: "string", text: token.text, line: token.line };
  }
  if (token.kind === "punct" && token.text === "{") return objectLiteral(cursor);
  if (token.kind === "punct" && token.text === "[") return arrayLiteral(cursor);
  if (token.kind === "word") {
    cursor.at += 1;
    return { kind: "string", text: token.text, line: token.line };
  }
  return undefined;
}

/** Reads `{ key: value, ... }`. A spread, a method, or a shorthand entry is skipped. */
function objectLiteral(cursor: Cursor): Literal {
  const line = cursor.tokens[cursor.at]!.line;
  cursor.at += 1;
  const entries: Field[] = [];
  while (cursor.at < cursor.tokens.length) {
    const token = cursor.tokens[cursor.at]!;
    if (token.kind === "punct" && token.text === "}") {
      cursor.at += 1;
      break;
    }
    if (token.kind === "punct" && token.text === ",") {
      cursor.at += 1;
      continue;
    }
    if (token.kind === "punct" && token.text === ".") {
      skipExpression(cursor);
      continue;
    }
    if (token.kind !== "string" && token.kind !== "word") {
      cursor.at += 1;
      continue;
    }
    cursor.at += 1;
    const colon = cursor.tokens[cursor.at];
    if (colon === undefined || colon.kind !== "punct" || colon.text !== ":") {
      skipEntry(cursor);
      continue;
    }
    cursor.at += 1;
    const value = literal(cursor);
    if (value === undefined) break;
    entries.push({ key: token.text, value, line: token.line });
  }
  return { kind: "object", entries, line };
}

/** Reads `[ value, ... ]`. */
function arrayLiteral(cursor: Cursor): Literal {
  const line = cursor.tokens[cursor.at]!.line;
  cursor.at += 1;
  const items: Literal[] = [];
  while (cursor.at < cursor.tokens.length) {
    const token = cursor.tokens[cursor.at]!;
    if (token.kind === "punct" && token.text === "]") {
      cursor.at += 1;
      break;
    }
    if (token.kind === "punct" && token.text === ",") {
      cursor.at += 1;
      continue;
    }
    if (token.kind === "punct" && token.text === ".") {
      skipExpression(cursor);
      continue;
    }
    const value = literal(cursor);
    if (value === undefined) break;
    items.push(value);
  }
  return { kind: "array", items, line };
}

/**
 * The object a sidebars file exports: after `module.exports =`, `export default`, or `const sidebars ... =`. Falls back
 * to the first object literal, which is what a JSON sidebars file is.
 */
function configLiteral(tokens: readonly Token[]): Literal | undefined {
  for (let at = 0; at < tokens.length; at += 1) {
    const token = tokens[at]!;
    if (token.kind !== "word" || !ANCHORS.has(token.text)) continue;
    for (let next = at + 1; next < tokens.length; next += 1) {
      const candidate = tokens[next]!;
      if (candidate.kind === "punct" && candidate.text === "{") {
        return objectLiteral({ tokens, at: next });
      }
    }
  }
  const first = tokens.findIndex((token) => token.kind === "punct" && token.text === "{");
  return first === -1 ? undefined : objectLiteral({ tokens, at: first });
}

/** A diagnostic at one line of the sidebar file. */
function finding(id: string, message: string, file: string, line: number): Diagnostic {
  return { id, severity: "warning", message, pos: { file, line, column: 1, endLine: line, endColumn: 1 } };
}

/** A field's value when it is a string literal. */
function textField(value: Literal | undefined): string | undefined {
  return value?.kind === "string" ? value.text : undefined;
}

/** The field named `key` in an object literal. */
function field(value: Literal, key: string): Literal | undefined {
  return value.kind === "object" ? value.entries.find((entry) => entry.key === key)?.value : undefined;
}

/** The page URL for a doc id, or a warning that no imported page carries it. */
function docLink(
  id: string,
  line: number,
  label: string | undefined,
  pages: ReadonlyMap<string, SidebarPage>,
  file: string,
  diagnostics: Diagnostic[],
): NavLink | undefined {
  const page = pages.get(id);
  if (page === undefined) {
    diagnostics.push(finding("import.sidebar-unknown-doc", `the sidebar names \`${id}\`, which is not an imported page; its link is left out.`, file, line));
    return undefined;
  }
  return { title: label ?? page.title, url: page.url };
}

/** One item as a link: a doc id, a doc entry, or a link entry. `undefined` when it is not a link or needs a group. */
function linkItem(
  item: Literal,
  pages: ReadonlyMap<string, SidebarPage>,
  file: string,
  diagnostics: Diagnostic[],
): NavLink | undefined {
  if (item.kind === "string") return docLink(item.text, item.line, undefined, pages, file, diagnostics);
  if (item.kind !== "object") return undefined;
  const type = textField(field(item, "type"));
  const label = textField(field(item, "label"));
  const href = textField(field(item, "href"));
  if (type === "link" || (type === undefined && href !== undefined)) {
    if (label === undefined || href === undefined) {
      diagnostics.push(finding("import.sidebar-invalid-link", "a `link` entry needs `label` and `href`; it is left out.", file, item.line));
      return undefined;
    }
    return { title: label, url: href };
  }
  const id = textField(field(item, "id"));
  if ((type === "doc" || type === undefined) && id !== undefined) {
    return docLink(id, item.line, label, pages, file, diagnostics);
  }
  return undefined;
}

/** The last segment of a folder path, which Docusaurus uses as a category's default label. */
function folderName(folder: string): string {
  return folder.slice(folder.lastIndexOf("/") + 1);
}

/** The value an optional position sorts at; unpositioned entries come last. */
function order(position: number | undefined): number {
  return position ?? Number.POSITIVE_INFINITY;
}

/** Compares by code point, never by locale. */
function byCodePoint(a: string, b: string): number {
  return a < b ? -1 : a > b ? 1 : 0;
}

/** Every link in a list, with a group replaced by its flattened children. */
export function flatLinks(items: readonly NavItem[]): NavLink[] {
  return items.flatMap((item) => ("url" in item ? [item] : flatLinks(item.children)));
}

/**
 * Rebuilds one `autogenerated` list from the pages' folder structure. A page directly in `dirName` is a link, a
 * folder becomes a group titled by its `_category_` file (or its name), and both keep `position` then name order.
 * A folder's deeper subfolders are flattened into it, because this engine's groups hold links only.
 */
function autoItems(
  dirName: string,
  pages: readonly SidebarPage[],
  categories: ReadonlyMap<string, CategoryMeta>,
  file: string,
  line: number,
  diagnostics: Diagnostic[],
): NavItem[] {
  const dir = dirName === "." ? "" : dirName.replace(/^\.\/|\/+$/g, "");
  const base = dir === "" ? "" : `${dir}/`;
  const inside = pages.filter((page) => page.id.startsWith(base));
  if (inside.length === 0) {
    diagnostics.push(finding("import.sidebar-autogenerated", `the autogenerated list names \`${dirName}\`, which has no imported pages; nothing is added for it.`, file, line));
    return [];
  }

  const rows: { order: number; label: string; id: string; page?: SidebarPage }[] = [];
  const folders = new Set<string>();
  for (const page of inside) {
    const rest = page.id.slice(base.length);
    const slash = rest.indexOf("/");
    if (slash === -1) rows.push({ order: order(page.position), label: page.title, id: page.id, page });
    else folders.add(rest.slice(0, slash));
  }
  for (const folder of folders) {
    const meta = categories.get(`${base}${folder}`);
    rows.push({ order: order(meta?.position), label: meta?.label ?? folderName(folder), id: `${base}${folder}` });
  }
  rows.sort((a, b) => a.order - b.order || byCodePoint(a.label, b.label) || byCodePoint(a.id, b.id));

  return rows.flatMap((row): NavItem[] => {
    if (row.page !== undefined) return [{ title: row.page.title, url: row.page.url }];
    const children = inside
      .filter((page) => page.id.startsWith(`${row.id}/`))
      .sort((a, b) => order(a.position) - order(b.position) || byCodePoint(a.title, b.title) || byCodePoint(a.id, b.id));
    if (children.length === 0) return [];
    return [{ title: row.label, children: children.map((page) => ({ title: page.title, url: page.url })) }];
  });
}

/** A `ref`'s sidebar id and list, or `undefined` with a report when it names nothing or cycles. */
function referencedList(
  item: Literal,
  lists: ReadonlyMap<string, readonly Literal[]>,
  file: string,
  diagnostics: Diagnostic[],
  seen: ReadonlySet<string>,
): { readonly id: string; readonly list: readonly Literal[] } | undefined {
  if (item.kind !== "object") return undefined;
  const id = textField(field(item, "id"));
  const list = id === undefined ? undefined : lists.get(id);
  if (id === undefined || list === undefined) {
    diagnostics.push(finding("import.sidebar-unknown-ref", "a `ref` entry names no sidebar in this file; it is left out.", file, item.line));
    return undefined;
  }
  return seen.has(id) ? undefined : { id, list };
}

/** The links of a category, flattening its nested categories, refs, and generated folders in place. */
function linksOf(
  items: readonly Literal[],
  pages: ReadonlyMap<string, SidebarPage>,
  allPages: readonly SidebarPage[],
  categories: ReadonlyMap<string, CategoryMeta>,
  lists: ReadonlyMap<string, readonly Literal[]>,
  file: string,
  diagnostics: Diagnostic[],
  seen: ReadonlySet<string>,
): NavLink[] {
  const links: NavLink[] = [];
  for (const item of items) {
    if (item.kind === "object" && textField(field(item, "type")) === "autogenerated") {
      const dirName = textField(field(item, "dirName")) ?? ".";
      links.push(...flatLinks(autoItems(dirName, allPages, categories, file, item.line, diagnostics)));
      continue;
    }
    if (item.kind === "object") {
      const type = textField(field(item, "type"));
      if (type === "category") {
        const children = field(item, "items");
        if (children?.kind === "array") {
          links.push(...linksOf(children.items, pages, allPages, categories, lists, file, diagnostics, seen));
        }
        continue;
      }
      if (type === "ref") {
        const referenced = referencedList(item, lists, file, diagnostics, seen);
        if (referenced !== undefined) {
          links.push(
            ...linksOf(referenced.list, pages, allPages, categories, lists, file, diagnostics, new Set([...seen, referenced.id])),
          );
        }
        continue;
      }
    }
    const link = linkItem(item, pages, file, diagnostics);
    if (link !== undefined) links.push(link);
  }
  return links;
}

/**
 * Appends one list's navigation entries. A category becomes a group, refs expand in place, an autogenerated list
 * becomes the groups its folders give it, and every other item is a link. The engine's groups hold links only, so a
 * category's nested groups are flattened by {@link linksOf}.
 */
function appendItems(
  items: readonly Literal[],
  out: NavItem[],
  pages: ReadonlyMap<string, SidebarPage>,
  allPages: readonly SidebarPage[],
  categories: ReadonlyMap<string, CategoryMeta>,
  lists: ReadonlyMap<string, readonly Literal[]>,
  file: string,
  diagnostics: Diagnostic[],
  seen: ReadonlySet<string>,
): void {
  for (const item of items) {
    if (item.kind === "object" && textField(field(item, "type")) === "autogenerated") {
      const dirName = textField(field(item, "dirName")) ?? ".";
      out.push(...autoItems(dirName, allPages, categories, file, item.line, diagnostics));
      continue;
    }
    if (item.kind === "object" && textField(field(item, "type")) === "ref") {
      const referenced = referencedList(item, lists, file, diagnostics, seen);
      if (referenced === undefined) continue;
      appendItems(referenced.list, out, pages, allPages, categories, lists, file, diagnostics, new Set([...seen, referenced.id]));
      continue;
    }
    if (item.kind === "object" && textField(field(item, "type")) === "category") {
      const label = textField(field(item, "label"));
      const children = field(item, "items");
      if (label === undefined || children?.kind !== "array") {
        diagnostics.push(finding("import.sidebar-invalid-category", "a `category` entry needs `label` and `items`; it is left out.", file, item.line));
        continue;
      }
      // shortcut: a clickable category's own `link` has no group equivalent here and is dropped.
      const links = linksOf(children.items, pages, allPages, categories, lists, file, diagnostics, seen);
      if (links.length === 0) continue;
      const group: NavGroup = { title: label, children: links };
      out.push(group);
      continue;
    }
    const link = linkItem(item, pages, file, diagnostics);
    if (link !== undefined) out.push(link);
  }
}

/** What {@link convertSidebar} may account for besides the file itself. */
export interface SidebarOptions {
  /** Category labels and positions from the section's `_category_` files, by folder path inside the section. */
  readonly categories?: ReadonlyMap<string, CategoryMeta>;
}

/**
 * Converts the sidebar file at `file`. Each top-level sidebar is flattened into one list in declaration order. A file
 * with no sidebar list, or one that is not an object literal, contributes no navigation.
 */
export function convertSidebar(
  source: string,
  file: string,
  pages: readonly SidebarPage[],
  options: SidebarOptions = {},
): SidebarImport {
  const root = configLiteral(tokenize(source));
  if (root === undefined || root.kind !== "object") {
    return {
      items: [],
      diagnostics: [finding("import.sidebar-unreadable", "the sidebar file is not an object literal; the navigation is not converted.", file, 1)],
    };
  }

  const lists = new Map<string, readonly Literal[]>();
  for (const entry of root.entries) {
    if (entry.value.kind === "array") lists.set(entry.key, entry.value.items);
  }
  if (lists.size === 0) return { items: [], diagnostics: [] };

  const byId = new Map(pages.map((page) => [page.id, page]));
  const categories = options.categories ?? new Map<string, CategoryMeta>();
  const diagnostics: Diagnostic[] = [];
  const items: NavItem[] = [];
  for (const [, list] of lists) {
    appendItems(list, items, byId, pages, categories, lists, file, diagnostics, new Set());
  }
  return { items, diagnostics };
}
